const input = require("fs").readFileSync(0, "utf8");

function countAllWords(text) {
  let count = 0;
  for (const line of text.split("\n")) {
    count += line.split(" ").filter((word) => word !== "").length;
  }
  return count;
}

console.log(countAllWords(input));

