#include <iostream>
#include <sstream>
#include <string>

int countAllWords(std::istream& in) {
    int count = 0;
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream words(line);
        std::string word;
        while (words >> word) {
            count++;
        }
    }
    return count;
}

int main() {
    std::cout << countAllWords(std::cin) << "\n";
    return 0;
}

