package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func countAllWords(scanner *bufio.Scanner) int {
	count := 0
	for scanner.Scan() {
		count += len(strings.Fields(scanner.Text()))
	}
	return count
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Println(countAllWords(scanner))
}

